public static class GuxuExplorationLoadoutCheck {
 const BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Instance;
 static readonly List<string> evidence=new List<string>();static bool running;static int assertions;
 [MenuItem("GXDL/QA/UIStyle Difficulty")]
 public static void Difficulty()=>Begin(DifficultyRun(),"difficulty");
 [MenuItem("GXDL/QA/UIStyle Tower")]
 public static void Tower()=>Begin(TowerRun(),"tower");
 [MenuItem("GXDL/QA/UIStyle Loadout")]
 public static void Loadout()=>Begin(LoadoutRun(),"loadout");
 [MenuItem("GXDL/QA/UIStyle Growth Resize")]
 public static void GrowthResize()=>Begin(GrowthResizeRun(),"growth-resize");
 static void Begin(IEnumerator routine,string name){if(running||!Application.isPlaying||!GxdlGame.Instance.CanPlay)throw new Exception("Use offline preview with no active review");evidence.Clear();assertions=0;GuxuUI23Review.BeginStyle();running=true;GxdlGame.Instance.StartCoroutine(Guard(routine,name));}
 static void Require(bool pass,string message){assertions++;if(!pass)throw new Exception(message);evidence.Add("PASS "+message);}
 static IEnumerator Guard(IEnumerator routine,string name){var stack=new Stack<IEnumerator>();stack.Push(routine);bool passed=false;try{while(stack.Count>0){bool more;object value=null;try{more=stack.Peek().MoveNext();if(more)value=stack.Peek().Current;}catch(Exception error){evidence.Add("FAIL "+error);Debug.LogException(error);yield break;}if(!more){(stack.Pop() as IDisposable)?.Dispose();continue;}if(value is IEnumerator nested)stack.Push(nested);else yield return value;}passed=true;}finally{while(stack.Count>0)(stack.Pop() as IDisposable)?.Dispose();GuxuUI23Review.End();running=false;string report=DateTime.UtcNow.ToString("O")+" "+(passed?"PASS":"FAIL")+" "+assertions+" assertions\nSession: "+GuxuUI23Review.ActiveOutput+"\n"+string.Join("\n",evidence)+"\nRESTORED via isolated review fixture";File.WriteAllText("Reference/UIStyleRework20261111/technical/"+name+"-check.txt",report);File.WriteAllText(GuxuUI23Review.ActiveOutput+"/"+name+"-check.txt",report);}}
 static IEnumerator Action(string action,string name="",string scenario="",int height=1334,float delta=0)=>GuxuUI23Review.Run(new GuxuUI23Review.Command{action=action,name=name,scenario=scenario,height=height,delta=delta});
 static Text Text(string name)=>UnityEngine.Object.FindObjectsOfType<Text>().Single(t=>t.name==name&&t.gameObject.activeInHierarchy);
 static Button Button(string name)=>UnityEngine.Object.FindObjectsOfType<Button>().Single(t=>t.name==name&&t.gameObject.activeInHierarchy);
 static string Save()=>JsonConvert.SerializeObject(GxdlGame.Instance.Rules.Save);
 static void CheckTexture(string key,int width,int height,int limit){string path="Assets/Resources/Game/Guxu/Expansion/UI/"+key+".png";var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);var importer=AssetImporter.GetAtPath(path) as TextureImporter;Require(texture&&texture.width==width&&texture.height==height&&importer&&importer.maxTextureSize==limit&&!importer.mipmapEnabled&&importer.npotScale==TextureImporterNPOTScale.None,"actual production texture size and importer "+key);}
 static void RewardText(GuxuReward reward,string prefix){var values=reward.ToString().Split(new[]{"  "},StringSplitOptions.RemoveEmptyEntries);for(int i=0;i<values.Length;i++)Require(Text(prefix+" Value "+i).text==values[i],prefix+" real value "+i);}
 static IEnumerator WaitBattle(GuxuBattle battle){float deadline=Time.realtimeSinceStartup+100;while(GxdlGame.Instance.ActiveBattle!=null&&Time.realtimeSinceStartup<deadline)yield return null;Require(battle.Completed,"actual battle completed before deadline");}
 static IEnumerator GrowthResizeRun(){
  var g=GxdlGame.Instance;yield return Action("scenario",scenario:"growth");yield return Action("size",height:1334);g.ShowGrowthHub();yield return Action("inspect");string save=Save();
  foreach(int height in new[]{1624,1334,1624}){
   yield return Action("size",height:height);var rect=GameObject.Find("Growth Hub").GetComponent<RectTransform>();var corners=new Vector3[4];rect.GetWorldCorners(corners);var camera=rect.GetComponentInParent<Canvas>().worldCamera;
   Require(corners.All(c=>{var point=RectTransformUtility.WorldToScreenPoint(camera,c);return point.x>=-1&&point.y>=-1&&point.x<=Screen.width+1&&point.y<=Screen.height+1;}),"live resize retains complete composition "+height);
   Require(Text("Growth Balance Forge").text=="玄铁 "+g.Rules.Save.forgeOre&&Text("Growth Power").text=="战力 "+g.Rules.Attributes.Power,"live resize keeps real labels "+height);
   yield return Action("click","Growth Realm");Require(g.ExpansionScreen=="realm","resized hub pointer opens realm "+height);yield return Action("click","返回修行");Require(g.ExpansionScreen=="growth"&&Save()==save,"return and resize preserve save "+height);
  }
  yield return Action("click","Growth Loadout");Require(g.ExpansionScreen=="loadout","bottom target also remains accessible after resize");
 }
 static IEnumerator DifficultyRun(){
  var g=GxdlGame.Instance;var r=g.Rules;Require(GuxuUiArt.Optional("difficulty-path")&&GuxuUiArt.Optional("difficulty-node"),"production difficulty path and tier plaque imported");CheckTexture("difficulty-path",750,808,1024);CheckTexture("difficulty-node",256,192,256);
  Array.Clear((int[])typeof(GxdlGame).GetField("difficultySelections",Private).GetValue(g),0,4);yield return Action("scenario",scenario:"combat");yield return Action("size",height:1334);g.ShowDungeon(1);yield return Action("inspect");
  Require(Text("Difficulty Attempts").text.StartsWith("今日剩余 3 次")&&Text("Difficulty Selection Title").text=="难度 1 · 可挑战","initial real tier and attempt state");
  Require(UnityEngine.Object.FindObjectsOfType<Button>().Count(b=>b.name.StartsWith("Difficulty Node "))==10&&UnityEngine.Object.FindObjectsOfType<Button>().Where(b=>b.name.StartsWith("Difficulty Node ")).All(b=>((RectTransform)b.transform).rect.width>=64&&((RectTransform)b.transform).rect.height>=64),"all ten nodes have independent accessible touch rectangles");
  string save=Save();yield return Action("drag","Difficulty Path Viewport",delta:-250);
  for(int tier=10;tier>=1;tier--){yield return Action("click","Difficulty Node "+tier);var stage=GuxuStageConfig.Load().Dungeon(1,tier);RewardText(GuxuStageRules.Reward(stage,true),"Difficulty Reward");Require(Button("Difficulty Challenge").interactable==GuxuStageRules.CanEnter(stage,r.Save)&&!Button("Difficulty Sweep").interactable,"selected tier uses actual entry and sweep rules "+tier);}
  Require(Save()==save,"selecting every tier and viewing locked rewards spends nothing");yield return Action("click","Difficulty Node 2");yield return Action("reject-click","Difficulty Challenge");Require(Save()==save,"locked challenge rejects without mutation");
  yield return Action("size",height:1624);Require(Text("Difficulty Selection Title").text.StartsWith("难度 2"),"resize preserves selected difficulty");yield return Action("click","Difficulty Node 1");
  int dust=r.Save.coins;var expected=GuxuStageRules.Reward(GuxuStageConfig.Load().Dungeon(1,1),true);int gems=r.Save.gemInventory[expected.gemIndex];typeof(GxdlGame).GetField("fightSpeed",Private).SetValue(g,4);
  yield return Action("click","Difficulty Challenge");Require(g.CurrentStage.contentId==1&&g.CurrentStage.difficulty==1,"single primary opens actual chosen encounter");yield return Action("click","Ruins Challenge");var battle=g.ActiveBattle;yield return WaitBattle(battle);
  Require(battle.Won&&battle.Settled&&r.Save.dungeonClears[1]==1&&r.Save.dungeonClaims[1]==1&&r.Save.coins==dust+expected.dust&&r.Save.gemInventory[expected.gemIndex]==gems+expected.gems,"real first win pays canonical gems and dust and one daily claim");yield return Action("click","Close Modal");
  Require(Text("Difficulty Reward State").text=="已首通 · 常规奖励"&&Button("Difficulty Sweep").interactable,"return after first clear refreshes reward semantics and sweep action");RewardText(GuxuStageRules.Reward(GuxuStageConfig.Load().Dungeon(1,1),false),"Difficulty Reward");
  yield return Action("click","Difficulty Sweep");yield return Action("click","Difficulty Sweep");save=Save();Require(r.Save.dungeonClaims[1]==3&&!Button("Difficulty Sweep").interactable&&!Button("Difficulty Challenge").interactable&&Text("Difficulty Attempts").text.StartsWith("今日剩余 0 次"),"two actual sweeps exhaust cap and refresh both controls");yield return Action("reject-click","Difficulty Sweep");yield return Action("reject-click","Difficulty Challenge");Require(save==Save(),"exhausted actions protect resources");yield return Action("click","Difficulty Back");Require(Text("Dungeon Progress 1").text=="已通关 1 / 10"&&Text("Dungeon Attempts 1").text=="今日剩余 0 次","courtyard reflects actual completion and exhaustion");
  foreach(int kind in new[]{0,2,3}){g.ShowDungeon(kind);yield return Action("inspect");RewardText(GuxuStageRules.Reward(GuxuStageConfig.Load().Dungeon(kind,1),true),"Difficulty Reward");Require(Text("Difficulty Name").text==GuxuStageRules.DungeonNames[kind],"shared path preserves real resource identity "+kind);}
  yield return Action("scenario",scenario:"defeat");r.Save.stage=21;g.ShowDungeon(1);r.RefreshDaily(DateTime.UtcNow);save=Save();yield return Action("click","Difficulty Challenge");yield return Action("click","Ruins Challenge");battle=g.ActiveBattle;yield return WaitBattle(battle);Require(!battle.Won&&Save()==save&&r.Save.dungeonClaims[1]==0,"actual failed dungeon spends no claims or resources");yield return Action("click","Close Modal");yield return Action("size",height:1334);
 }
 static IEnumerator TowerRun(){
  var g=GxdlGame.Instance;var r=g.Rules;Require(GuxuUiArt.Optional("tower-tier"),"production repeatable tower tier imported");CheckTexture("tower-tier",512,200,512);typeof(GxdlGame).GetField("towerPage",Private).SetValue(g,-1);yield return Action("scenario",scenario:"combat");yield return Action("size",height:1334);g.ShowTower();yield return Action("inspect");
  var first=GuxuStageConfig.Load().tower[0];Require(Text("Tower Enemy Name").text==first.guardianName&&!first.boss&&Text("Tower Progress").text=="已登临 0 / 100 层","first floor uses actual guard and progress without fake Boss");RewardText(GuxuStageRules.Reward(first,true),"Tower Reward");
  string save=Save();yield return Action("click","Tower Marker 10");Require(Text("Tower Enemy Name").text.Contains(GuxuStageConfig.Load().tower[9].guardianName)&&!Button("Tower Challenge").interactable,"tenth floor shows actual Boss while future challenge remains locked");yield return Action("reject-click","Tower Challenge");Require(save==Save(),"future floor preview protects save");
  for(int segment=0;segment<10;segment++){Require(Text("Tower Segment Label").text==(segment*10+1)+"—"+(segment*10+10)+"层","correct decade label "+segment);Require(UnityEngine.Object.FindObjectsOfType<Button>().Count(b=>b.name.StartsWith("Tower Floor "))==10,"ten floors in segment "+segment);yield return Action("click","Tower Marker "+(segment*10+1));yield return Action("click","Tower Marker "+(segment*10+10));if(segment<9)yield return Action("click","Tower Next Segment");}
  Require(!Button("Tower Next Segment").interactable&&Text("Tower Selection Title").text.StartsWith("第 100 层")&&save==Save(),"all100 floors reachable by ten segments without progression mutation");
  typeof(GxdlGame).GetField("towerPage",Private).SetValue(g,-1);g.ShowTower();yield return Action("size",height:1624);yield return Action("drag","Tower Climb Viewport",delta:-350);yield return Action("click","Tower Marker 1");yield return Action("click","Tower Floor 1");Require(Text("Tower Selection Title").text=="第 1 层 · 当前目标","actual floor entrance selects the same detail as the index");typeof(GxdlGame).GetField("fightSpeed",Private).SetValue(g,4);int[] before={r.Save.peaches,r.Save.coins,r.Save.forgeOre,r.Save.insight};var reward=GuxuStageRules.Reward(first,true);
  yield return Action("click","Tower Challenge");yield return Action("click","Ruins Challenge");var battle=g.ActiveBattle;yield return WaitBattle(battle);Require(battle.Won&&r.Save.towerFloor==2&&r.Save.peaches-before[0]==reward.seals&&r.Save.coins-before[1]==reward.dust&&r.Save.forgeOre-before[2]==reward.ore&&r.Save.insight-before[3]==reward.insight,"actual tower first clear grants all four resources once");yield return Action("click","Close Modal");Require(Text("Tower Current Target").text=="当前目标 · 第 2 层"&&Text("Tower Progress").text=="已登临 1 / 100 层","result return immediately advances real tower focus");
  yield return Action("click","Tower Marker 1");save=Save();Require(GameObject.Find("Tower Reward Icon 0")==null&&Text("Tower Condition").text.Contains("不再"),"revisited floor explicitly has no first-clear rewards");yield return Action("click","Tower Challenge");yield return Action("click","Ruins Challenge");battle=g.ActiveBattle;yield return WaitBattle(battle);Require(battle.Won&&Save()==save,"actual repeated floor cannot grant rewards or advance again");yield return Action("click","Close Modal");
  r.Save.towerFloor=101;g.ShowTower();yield return Action("inspect");Require(Text("Tower Current Target").text=="百层已通关"&&Text("Tower Progress").text=="已登临 100 / 100 层"&&UnityEngine.Object.FindObjectsOfType<Button>().All(b=>b.name!="Tower Floor 101"),"tower complete state has no invented floor101");
  yield return Action("scenario",scenario:"new");g.ShowTower();yield return Action("inspect");save=Save();yield return Action("reject-click","Tower Challenge");Require(save==Save()&&Text("Tower Condition").text.Contains("第15关"),"main-stage tower unlock remains authoritative");
 }
 static IEnumerator LoadoutRun(){
  var g=GxdlGame.Instance;var r=g.Rules;Require(GuxuUiArt.Optional("loadout-altar"),"production neutral skill altar imported");CheckTexture("loadout-altar",512,512,512);yield return Action("scenario",scenario:"combat");yield return Action("size",height:1334);g.ShowLoadout();yield return Action("inspect");
  int equipped=r.Save.activeSkill;string save=Save();int preview=(equipped+1)%4;yield return Action("click","Loadout Skill "+preview);Require(r.Save.activeSkill==equipped&&Save()==save&&GameObject.Find("Loadout Equipped Flag "+equipped)&&Text("Loadout Selected Name").text==GameRules.SkillNames[preview]&&Text("Loadout Skill Description").text==GameRules.SkillDetails[preview],"preview selection and equipped skill remain distinct with canonical details");
  yield return Action("click","Loadout Equip");Require(r.Save.activeSkill==preview&&GameObject.Find("Loadout Equipped Flag "+preview)&&!Button("Loadout Equip").interactable,"actual equip immediately moves flag and disables duplicate equip");
  for(int skill=0;skill<4;skill++){yield return Action("click","Loadout Skill "+skill);if(r.Save.activeSkill!=skill)yield return Action("click","Loadout Equip");Require(r.Save.activeSkill==skill&&Text("Loadout Skill Description").text==GameRules.SkillDetails[skill]&&UnityEngine.Object.FindObjectsOfType<Text>().Count(t=>t.name.StartsWith("Loadout Equipped Flag "))==1,"all four skills equip exactly one real slot "+skill);}
  bool automatic=r.Save.autoSkill;yield return Action("click","Loadout Auto");Require(r.Save.autoSkill!=automatic&&Button("Loadout Auto").GetComponentInChildren<Text>().text.Contains(r.Save.autoSkill?"开":"关"),"auto policy toggles real save and label immediately");yield return Action("size",height:1624);Require(Text("Loadout Selected Name").text==GameRules.SkillNames[3],"long screen preserves selected skill");g.ShowGrowthHub();g.ShowLoadout();yield return Action("inspect");Require(GameObject.Find("Loadout Equipped Flag 3")&&r.Save.activeSkill==3,"reentry reflects same equipped skill");
  g.ShowBattlePrep(GuxuStageConfig.Load().stages[139]);yield return Action("inspect");Require(Text("Prep Skill Detail").text==GameRules.SkillDetails[3]&&Text("Prep Skill Mode").text.Contains(r.Save.autoSkill?"自动":"手动"),"battle preparation consumes same skill and auto save");yield return Action("click","Ruins Challenge");Require(g.ActiveBattle!=null&&g.ActiveBattle.Skill==3&&g.ActiveBattle.AutoSkill==r.Save.autoSkill,"actual battle initializes from selected real skill and mode");yield return Action("click","退出挑战");yield return new WaitForSeconds(.5f);g.ShowLoadout();yield return Action("size",height:1334);yield return Action("click","Loadout Challenge");Require(g.ExpansionScreen=="world","primary challenge navigation works");
 }
}
